#!/usr/bin/env bun
/**
 * provision-inbound.ts — Idempotent inbound-agent provisioning for a Code Ninjas centre.
 *
 * Closes the gap in onboard-centre.ts (which only provisions outbound).
 * Does the 5 manual steps that were happening ad-hoc for EG, Leaside, StCath:
 *   1. Clone EG-Inbound LLM, swap {{LOCATION_NAME}} for the centre name
 *   2. Clone EG-Inbound agent, point at new LLM, set name CNKB-{Centre}-Inbound
 *   3. Set phone number's inbound_agent_id + inbound_webhook_url
 *   4. Add entry to PHONE_TO_CENTRE in multicentre pre-call workflow
 *   5. Smoke-test by triggering webhook with the new number, expect non-empty KB
 *
 * Idempotent: skips steps already done. Safe to re-run.
 *
 * Usage:
 *   RETELL_API_KEY=... N8N_API_KEY=... bun run provision-inbound.ts --centre st-catharines-on-ca
 *   ... --dry-run        Preview without writing
 */

import { parseArgs } from "util";
import { execFileSync } from "child_process";

const SOURCE_INBOUND_LLM_ID = "llm_6d77f36696f6fbfad97d03fa5ef8";
const SOURCE_INBOUND_AGENT_ID = "agent_17d623c8a8f95fc674288d0e00";
const MULTICENTRE_WORKFLOW_ID = "QFxDu1MBooL332PN";
const MULTICENTRE_WEBHOOK_URL = "https://xprime17.app.n8n.cloud/webhook/inbound-kb-injection-eg";
// export?format=csv serves fresh data; gviz/tq caches for minutes and returned
// stale rows during the 2026-06-12 Burlington provisioning
const CENTRE_LOOKUP_CSV = "https://docs.google.com/spreadsheets/d/1wQAdX3frfxCHK0HmGCKRpzmOx7SFaLP-3nn7AEc0GK0/export?format=csv&gid=0";
const RETELL_BASE = "https://api.retellai.com";
const N8N_BASE = "https://xprime17.app.n8n.cloud/api/v1";

const { values: args } = parseArgs({
  options: {
    centre: { type: "string", short: "c" },
    "dry-run": { type: "boolean", default: false },
  },
  strict: true,
});

const CENTRE_ID = args.centre;
if (!CENTRE_ID) { console.error("Pass --centre <centre_id>"); process.exit(1); }
const DRY = args["dry-run"] ?? false;

const RETELL_KEY = process.env.RETELL_API_KEY;
const N8N_KEY = process.env.N8N_API_KEY;
if (!RETELL_KEY || !N8N_KEY) { console.error("Set RETELL_API_KEY + N8N_API_KEY"); process.exit(1); }

async function rGet(path: string) {
  const r = await fetch(`${RETELL_BASE}${path}`, { headers: { Authorization: `Bearer ${RETELL_KEY}` } });
  if (!r.ok) throw new Error(`Retell GET ${path} ${r.status}`);
  return r.json();
}
async function rPost(path: string, body: any) {
  const r = await fetch(`${RETELL_BASE}${path}`, {
    method: "POST",
    headers: { Authorization: `Bearer ${RETELL_KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`Retell POST ${path} ${r.status}: ${await r.text()}`);
  return r.json();
}
async function rPatch(path: string, body: any) {
  const r = await fetch(`${RETELL_BASE}${path}`, {
    method: "PATCH",
    headers: { Authorization: `Bearer ${RETELL_KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`Retell PATCH ${path} ${r.status}: ${await r.text()}`);
  return r.json();
}

async function lookupCentre(centreId: string) {
  const r = await fetch(CENTRE_LOOKUP_CSV);
  const csv = await r.text();
  // proper CSV parse — export?format=csv only quotes fields that need it,
  // so the old split('","') (gviz always-quoted format) no longer works
  function parseLine(line: string): string[] {
    const cols: string[] = [];
    let cur = "", inQ = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') { inQ = !inQ; continue; }
      if (ch === "," && !inQ) { cols.push(cur.trim()); cur = ""; continue; }
      cur += ch;
    }
    cols.push(cur.trim());
    return cols;
  }
  const rows = csv.split("\n").map(parseLine);
  const hdr = rows[0];
  const idx = (col: string) => hdr.findIndex(h => h === col);
  const row = rows.find(r => r[idx("centre_id")] === centreId);
  if (!row) throw new Error(`Centre ${centreId} not in lookup sheet`);
  return {
    centre_id: row[idx("centre_id")],
    location_name: row[idx("location_name")],
    // from_number was split into inbound_number/outbound_number on 2026-06-08
    // (single-number centres carry the same value in both)
    from_number: row[idx("inbound_number")],
    knowledge_base: row[idx("knowledge_base")],
  };
}

async function step1_llm(centreName: string): Promise<string> {
  console.log(`Step 1: clone inbound LLM, swap {{LOCATION_NAME}} → ${centreName}`);
  if (DRY) return "llm_dry_run";
  const src = await rGet(`/get-retell-llm/${SOURCE_INBOUND_LLM_ID}`);
  const stripped: any = { ...src };
  delete stripped.llm_id; delete stripped.version;
  delete stripped.last_modification_timestamp; delete stripped.is_published;
  if (typeof stripped.general_prompt === "string") {
    stripped.general_prompt = stripped.general_prompt.replace(/East Gwillimbury/g, centreName);
  }
  if (typeof stripped.begin_message === "string") {
    stripped.begin_message = stripped.begin_message.replace(/East Gwillimbury/g, centreName);
  }
  const r = await rPost("/create-retell-llm", stripped);
  console.log(`  → llm_id ${r.llm_id}`);
  return r.llm_id;

