async function step2_agent(centreName: string, llmId: string): Promise<string> {
  console.log(`Step 2: clone inbound agent CNKB-${centreName}-Inbound`);
  if (DRY) return "agent_dry_run";
  const src = await rGet(`/get-agent/${SOURCE_INBOUND_AGENT_ID}`);
  const stripped: any = { ...src };
  delete stripped.agent_id; delete stripped.version; delete stripped.is_published;
  delete stripped.last_modification_timestamp; delete stripped.version_title;
  stripped.agent_name = `CNKB-${centreName.replace(/\s+/g, "")}-Inbound`;
  stripped.response_engine = { type: "retell-llm", llm_id: llmId, version: 0 };
  // Non-EG inbound clones post-call DIRECTLY to the n8n inbound EOC webhook —
  // only EG routes through ChatDash (the source agent's webhook_url would
  // otherwise leak EG's ChatDash agent onto every clone; StCath/Leaside pattern)
  stripped.webhook_url = "https://xprime17.app.n8n.cloud/webhook/inbound-end-of-call";
  const r = await rPost("/create-agent", stripped);
  console.log(`  → agent_id ${r.agent_id}`);
  return r.agent_id;
}

async function step3_phone(fromNumber: string, agentId: string) {
  const e164 = fromNumber.startsWith("+") ? fromNumber : `+${fromNumber}`;
  console.log(`Step 3: wire phone ${e164} → inbound_agent_id + inbound_webhook_url`);
  if (DRY) return;
  await rPatch(`/update-phone-number/${e164}`, {
    // Retell deprecated singular inbound_agent_id (removal after 2026-03-31);
    // use weighted inbound_agents array. Single agent → weight 1.
    inbound_agents: [{ agent_id: agentId, weight: 1 }],
    inbound_webhook_url: MULTICENTRE_WEBHOOK_URL,
  });
  console.log(`  → phone wired`);
}

async function step4_multicentre(fromNumber: string, centreId: string, kbDocUrl: string) {
  const e164 = fromNumber.startsWith("+") ? fromNumber : `+${fromNumber}`;
  console.log(`Step 4: add ${e164} to PHONE_TO_CENTRE in workflow ${MULTICENTRE_WORKFLOW_ID}`);
  const r = await fetch(`${N8N_BASE}/workflows/${MULTICENTRE_WORKFLOW_ID}`, {
    headers: { "X-N8N-API-KEY": N8N_KEY! },
  });
  const wf = await r.json() as any;
  const resolveNode = wf.nodes.find((n: any) => n.name === "Resolve Centre");
  if (!resolveNode) throw new Error("Resolve Centre node not found");
  const code: string = resolveNode.parameters.jsCode;
  if (code.includes(`'${e164}'`)) { console.log(`  → already in registry, skipping`); return; }
  // Insert new entry before the closing brace of PHONE_TO_CENTRE
  const entry = `  // ${centreId}\n  '${e164}': { centre_id: '${centreId}', documentURL: '${kbDocUrl.replace(/\/edit.*$/, '/edit')}' },\n`;
  const newCode = code.replace(/(const PHONE_TO_CENTRE = \{[\s\S]*?)\n\};/, `$1\n${entry}};`);
  if (newCode === code) throw new Error("Failed to insert into PHONE_TO_CENTRE");
  resolveNode.parameters.jsCode = newCode;
  if (DRY) { console.log(`  → DRY: would insert ${e164}`); return; }
  // n8n PUT accepts ONLY {name, nodes, connections, settings} — allowlist instead
  // of stripping read-only fields (new fields keep appearing and 400 the PUT)
  const ALLOWED_SETTINGS = ["executionOrder","timezone","saveDataErrorExecution","saveDataSuccessExecution","saveManualExecutions","saveExecutionProgress","executionTimeout","errorWorkflow"];
  const settings: any = {};
  for (const k of ALLOWED_SETTINGS) if (wf.settings?.[k] !== undefined) settings[k] = wf.settings[k];
  const payload = { name: wf.name, nodes: wf.nodes, connections: wf.connections, settings };
  const put = await fetch(`${N8N_BASE}/workflows/${MULTICENTRE_WORKFLOW_ID}`, {
    method: "PUT",
    headers: { "X-N8N-API-KEY": N8N_KEY!, "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!put.ok) throw new Error(`n8n PUT ${put.status}: ${await put.text()}`);
  console.log(`  → registry updated`);
}

async function step5_smoketest(fromNumber: string) {
  const e164 = fromNumber.startsWith("+") ? fromNumber : `+${fromNumber}`;
  console.log(`Step 5: smoke-test webhook with ${e164}`);
  if (DRY) return;
  const r = await fetch(MULTICENTRE_WEBHOOK_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ call_inbound: { to_number: e164 } }),
  });
  const d = await r.json() as any;
  const kbLen = d._debug?.kb_len ?? 0;
  const missing = d._debug?.kb_missing ?? true;
  if (missing || kbLen < 100) throw new Error(`Smoke test FAILED: kb_len=${kbLen}, missing=${missing}`);
  console.log(`  → KB returned (${kbLen} chars) ✓`);
}

async function main() {
  console.log(`\nProvisioning inbound for ${CENTRE_ID}${DRY ? " (DRY RUN)" : ""}\n`);
  const c = await lookupCentre(CENTRE_ID);
  console.log(`Centre: ${c.location_name} | phone: ${c.from_number} | KB: ${c.knowledge_base}\n`);

  // Idempotency: if phone already has an inbound_agent_id matching CNKB-{Centre}-Inbound, skip 1+2.
  const e164 = c.from_number.startsWith("+") ? c.from_number : `+${c.from_number}`;
  const phone = await rGet(`/get-phone-number/${e164}`) as any;
  // New weighted inbound_agents array; fall back to legacy field during deprecation window.
  let agentId = phone.inbound_agents?.[0]?.agent_id ?? phone.inbound_agent_id;

  if (agentId) {
    const existing = await rGet(`/get-agent/${agentId}`) as any;
    console.log(`Step 1+2: SKIP (existing inbound agent ${agentId} = "${existing.agent_name}")`);
  } else {
    const llmId = await step1_llm(c.location_name);
    agentId = await step2_agent(c.location_name, llmId);
  }
  await step3_phone(c.from_number, agentId);
  await step4_multicentre(c.from_number, c.centre_id, c.knowledge_base);
  await step5_smoketest(c.from_number);
  await step6_slotroutinggate(agentId);
  console.log(`\nDone. Forward landline → ${e164} to go live.\n`);
}

// Gate: the new inbound agent MUST serve ITS OWN centre's tour slots, not EG's.
// Guards the 2026-06-18 class of bug (cloned agent inherited the generic /retell/get-slots
// URL -> calendar_api silently defaulted to east-gwillimbury). Fails provisioning if wrong.
async function step6_slotroutinggate(agentId: string) {
  console.log(`Step 6: slot-routing gate for ${agentId}`);
  if (DRY) return;
  const check = `${process.env.HOME}/.claude/skills/_N8N/Tools/SlotRoutingCheck.py`;
  try {
    const out = execFileSync("python3", [check, "--agent", agentId], {
      encoding: "utf8",
      env: { ...process.env, RETELL_API_KEY: RETELL_KEY },
    });
    console.log(out.split("\n").filter(l => l.includes("[") || l.includes("RESULT")).join("\n"));
    console.log(`  → slot routing verified (agent serves its own centre's slots) ✓`);
  } catch (e: any) {
    if (e.stdout) console.error(e.stdout);
    throw new Error(
      `Slot-routing gate FAILED for ${agentId}. The agent is not serving its own centre's slots ` +
      `(likely a generic get_tour_slots URL or the centre isn't in calendar_api CENTRES). ` +
      `Fix before going live — see SlotRoutingCheck output above.`
    );
  }
}

main().catch(e => { console.error(`\nFAILED: ${e.message}`); process.exit(1); });

