  console.log(`  → KB returned (${kbLen} chars) ✓`);
}

async function main() {
  console.log(`\nProvisioning inbound for ${CENTRE_ID}${DRY ? " (DRY RUN)" : ""}\n`);
  const c = await lookupCentre(CENTRE_ID);
  console.log(`Centre: ${c.location_name} | phone: ${c.from_number} | KB: ${c.knowledge_base}\n`);

  // Idempotency: if phone already has an inbound_agent_id matching CNKB-{Centre}-Inbound, skip 1+2.
  const e164 = c.from_number.startsWith("+") ? c.from_number : `+${c.from_number}`;
  const phone = await rGet(`/get-phone-number/${e164}`) as any;
  // New weighted inbound_agents array; fall back to legacy field during deprecation window.
  let agentId = phone.inbound_agents?.[0]?.agent_id ?? phone.inbound_agent_id;

  if (agentId) {
    const existing = await rGet(`/get-agent/${agentId}`) as any;
    console.log(`Step 1+2: SKIP (existing inbound agent ${agentId} = "${existing.agent_name}")`);
  } else {
    const llmId = await step1_llm(c.location_name);
    agentId = await step2_agent(c.location_name, llmId);
  }
  await step3_phone(c.from_number, agentId);
  await step4_multicentre(c.from_number, c.centre_id, c.knowledge_base);
  await step5_smoketest(c.from_number);
  await step6_slotroutinggate(agentId);
  console.log(`\nDone. Forward landline → ${e164} to go live.\n`);
}

// Gate: the new inbound agent MUST serve ITS OWN centre's tour slots, not EG's.
// Guards the 2026-06-18 class of bug (cloned agent inherited the generic /retell/get-slots
// URL -> calendar_api silently defaulted to east-gwillimbury). Fails provisioning if wrong.
async function step6_slotroutinggate(agentId: string) {
  console.log(`Step 6: slot-routing gate for ${agentId}`);
  if (DRY) return;
  const check = `${process.env.HOME}/.claude/skills/_N8N/Tools/SlotRoutingCheck.py`;
  try {
    const out = execFileSync("python3", [check, "--agent", agentId], {
      encoding: "utf8",
      env: { ...process.env, RETELL_API_KEY: RETELL_KEY },
    });
    console.log(out.split("\n").filter(l => l.includes("[") || l.includes("RESULT")).join("\n"));
    console.log(`  → slot routing verified (agent serves its own centre's slots) ✓`);
  } catch (e: any) {
    if (e.stdout) console.error(e.stdout);
    throw new Error(
      `Slot-routing gate FAILED for ${agentId}. The agent is not serving its own centre's slots ` +
      `(likely a generic get_tour_slots URL or the centre isn't in calendar_api CENTRES). ` +
      `Fix before going live — see SlotRoutingCheck output above.`
    );
  }
}

main().catch(e => { console.error(`\nFAILED: ${e.message}`); process.exit(1); });

