async function step8b_createKBDoc(state: OnboardingState): Promise<void> {
  stepHeader(9, "Knowledge Base — Create Google Doc");

  const centreDisplayName = state.discovery?.name ?? centreName;

  if (dryRun) {
    dryLog(`Would copy EG KB doc and rename for ${centreDisplayName}`);
    dryLog(`Would update centres.json and inbound webhook mapping`);
    return;
  }

  // 1. Read the EG reference doc content
  info("Reading EG reference KB doc...");
  const readRes = await fetch(N8N_KB_READ, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ doc_id: EG_KB_DOC_ID }),
  });
  if (!readRes.ok) throw new Error(`Failed to read EG KB doc: ${readRes.status}`);
  const egContent = (await readRes.json() as any).content ?? "";

  // 2. Create a new doc via Google Docs API (through n8n)
  //    We use the write webhook with a fresh doc — but we need the doc to exist first.
  //    The simplest approach: use Google Drive API via n8n to copy the doc.
  //    For now, we'll note the doc ID needs manual creation and populate it.
  info(`Template KB content: ${egContent.length} chars from EG reference doc`);

  // Create starter content with centre name
  const starterContent = egContent
    .replace(/East Gwillimbury/g, centreDisplayName)
    .replace(/eastgwillimburyonca@codeninjas\.com/g, `${centreDisplayName.toLowerCase().replace(/[^a-z]/g, "")}@codeninjas.com`)
    .replace(/905-478-1664/g, "(update phone number)")
    .replace(/19101A Leslie Street.*?L0G 1V0/g, "(update address)");

  warn(`ACTION REQUIRED: Create a new Google Doc for ${centreDisplayName} KB`);
  console.log(`
    1. Go to https://docs.google.com/document/create
    2. Name it: "Code Ninjas ${centreDisplayName} — Knowledge Base"
    3. Copy the doc ID from the URL (the long string between /d/ and /edit)
    4. Run the KB crawler to populate it:
       bun /root/kb-crawler/crawl.ts --centre <centre-id>
    5. Add the doc ID to /root/kb-crawler/centres.json
    6. Add the doc URL to the Centre Lookup Sheet knowledge_base column
  `);

  // Store a placeholder — the actual doc ID will need manual entry
  state.kbDocId = "PENDING";
  info(`KB doc creation noted. Update centres.json after creating the doc.`);
}
async function step8c_clickup(state: OnboardingState): Promise<void> {
  stepHeader(9, "ClickUp - Folder + Inbound/Outbound Lists");

  const folderName = state.discovery?.name ?? centreName;

  if (dryRun) {
    dryLog(`Would create ClickUp folder "${folderName}" in Voice AI space ${CLICKUP_VOICE_AI_SPACE}`);
    dryLog(`Would create "Inbound" and "Outbound" lists in that folder`);
    return;
  }

  if (!CLICKUP_TOKEN) {
    warn("CLICKUP_PERSONAL_TOKEN not set — skipping ClickUp provisioning (lists left blank; create manually).");
    return;
  }

  // Reuse an existing folder of the same name if present (idempotent re-runs)
  const existing = await clickupApi("GET", `/space/${CLICKUP_VOICE_AI_SPACE}/folder?archived=false`);
  let folder = (existing.folders ?? []).find((f: any) => f.name === folderName);
  if (folder) {
    info(`Reusing existing ClickUp folder "${folderName}" (${folder.id})`);
  } else {
    folder = await clickupApi("POST", `/space/${CLICKUP_VOICE_AI_SPACE}/folder`, { name: folderName });
    success(`Created ClickUp folder "${folderName}" (${folder.id})`);
  }

  // Ensure Inbound + Outbound lists exist in the folder
  const lists = await clickupApi("GET", `/folder/${folder.id}/list?archived=false`);
  const byName: Record<string, string> = {};
  for (const l of (lists.lists ?? [])) byName[l.name] = l.id;

  async function ensureList(name: string): Promise<string> {
    if (byName[name]) {
      info(`Reusing existing "${name}" list (${byName[name]})`);
      return byName[name];
    }
    const l = await clickupApi("POST", `/folder/${folder.id}/list`, { name });
    success(`Created "${name}" list (${l.id})`);
    return l.id;
  }

  state.clickupInboundListId = await ensureList("Inbound");
  state.clickupOutboundListId = await ensureList("Outbound");

  ok(`ClickUp ready: inbound=${state.clickupInboundListId} outbound=${state.clickupOutboundListId}`);
  if (!state.clickupUserIds) {
    warn("No --clickup-user-ids provided — staff-follow-up tasks will be UNASSIGNED until a director guest is added.");
  }
}
